package com.example.domain.model.i18n

internal object DuaBn2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_muawwidhat" to DuaText("তিন কুল (মুআওয়িযাত)", "(সূরা ইখলাস) বলো: তিনি আল্লাহ, এক। আল্লাহ অমুখাপেক্ষী। তিনি কাউকে জন্ম দেননি এবং কারও থেকে জন্ম নেননি। আর তাঁর সমতুল্য কেউ নেই।\n\n(সূরা ফালাক) বলো: আমি আশ্রয় চাই প্রভাতের রবের কাছে, তাঁর সৃষ্টির অনিষ্ট থেকে, অন্ধকার রাতের অনিষ্ট থেকে যখন তা ছেয়ে যায়, গিরায় ফুঁকদানকারিণীদের অনিষ্ট থেকে, এবং হিংসুকের অনিষ্ট থেকে যখন সে হিংসা করে।\n\n(সূরা নাস) বলো: আমি আশ্রয় চাই মানুষের রবের কাছে, মানুষের বাদশাহর কাছে, মানুষের ইলাহের কাছে, আত্মগোপনকারী কুমন্ত্রণাদাতার অনিষ্ট থেকে, যে মানুষের অন্তরে কুমন্ত্রণা দেয়, জিন ও মানুষের মধ্য থেকে।", "সকাল-সন্ধ্যা তিনটি সূরা তিনবার করে, আর ঘুমানোর আগে হাতে ফুঁ দিয়ে শরীরে বুলানো।", "সকাল-সন্ধ্যা তিনবার পড়া সব কিছু থেকে যথেষ্ট হয়।"),
        "dua_sabr" to DuaText("ধৈর্য ও দৃঢ়তার জন্য", "হে আমাদের রব! আমাদের উপর ধৈর্য ঢেলে দাও, আমাদের পা দৃঢ় রাখো এবং কাফির সম্প্রদায়ের বিরুদ্ধে আমাদের সাহায্য করো।", "কঠিন সময় ও মোকাবেলার সময়।", "তালুতের বাহিনীর দোয়া।"),
        "dua_rabbana_innana_amanna" to DuaText("ক্ষমা ও আগুন থেকে রক্ষা", "হে আমাদের রব! আমরা ঈমান এনেছি, অতএব আমাদের গুনাহ ক্ষমা করো এবং আগুনের আজাব থেকে রক্ষা করো।", "কুরআনি দোয়া।", "মুত্তাকিদের গুণাবলিতে বর্ণিত দোয়া।"),
        "dua_rabbana_hab_lana_rahmah" to DuaText("আমাদের কাজে সঠিক পথ (আসহাবে কাহফ)", "হে আমাদের রব! তোমার পক্ষ থেকে আমাদের রহমত দাও এবং আমাদের কাজ সঠিকভাবে সম্পন্ন করার ব্যবস্থা করো।", "আসহাবে কাহফের দোয়া।", "সিদ্ধান্ত ও কঠিন অবস্থায় পথনির্দেশ।"),
        "dua_musa_faqir" to DuaText("রিজিকের জন্য মুসা (আ.)-এর দোয়া", "হে আমার রব! তুমি আমার প্রতি যে কল্যাণই নাজিল করো, আমি তার মুখাপেক্ষী।", "রিজিক ও কল্যাণ কামনা — মাদইয়ানে মুসা (আ.)-এর দোয়া।", "এই দোয়ার পর আল্লাহ মুসা (আ.)-কে ঘর, জীবিকা ও স্ত্রী দান করেন।"),
        "dua_ayyub" to DuaText("অসুস্থতায় আইয়ুব (আ.)-এর দোয়া", "(হে আমার রব!) আমাকে কষ্ট স্পর্শ করেছে, আর তুমি দয়ালুদের মধ্যে সর্বশ্রেষ্ঠ দয়ালু।", "অসুস্থতা ও কষ্টে।", "আল্লাহ আইয়ুব (আ.)-এর কষ্ট দূর করে দেন।"),
        "dua_husn_khatimah" to DuaText("মুসলিম হয়ে মৃত্যু (ইউসুফ আ.)", "হে আসমান ও জমিনের স্রষ্টা! তুমিই দুনিয়া ও আখিরাতে আমার অভিভাবক। আমাকে মুসলিম অবস্থায় মৃত্যু দাও এবং নেককারদের সাথে মিলিত করো।", "উত্তম মৃত্যুর দোয়া।", "ইউসুফ (আ.)-এর দোয়া।"),
        "dua_shaitan_hamazat" to DuaText("শয়তানের কুমন্ত্রণা থেকে আশ্রয়", "হে আমার রব! আমি শয়তানদের কুমন্ত্রণা থেকে তোমার আশ্রয় চাই, আর হে আমার রব! তাদের আমার কাছে আসা থেকেও তোমার আশ্রয় চাই।", "শয়তানি কুমন্ত্রণা থেকে আশ্রয়।", "কুরআনি আশ্রয়ের দোয়া।"),
        "dua_bad_character" to DuaText("মন্দ চরিত্র থেকে আশ্রয়", "হে আল্লাহ! আমি মন্দ চরিত্র, মন্দ কাজ ও মন্দ প্রবৃত্তি থেকে তোমার আশ্রয় চাই।", "মন্দ চরিত্র, কাজ ও প্রবৃত্তি থেকে আশ্রয়।", "নবী ﷺ-এর আশ্রয়ের দোয়া।"),
        "dua_zawal_nimah" to DuaText("নিয়ামত হারানো থেকে আশ্রয়", "হে আল্লাহ! আমি তোমার আশ্রয় চাই তোমার নিয়ামত চলে যাওয়া থেকে, তোমার দেওয়া নিরাপত্তা বদলে যাওয়া থেকে, তোমার আকস্মিক শাস্তি থেকে এবং তোমার সব অসন্তুষ্টি থেকে।", "নিয়ামত হারানো ও আকস্মিক বিপদ থেকে আশ্রয়।", "নবী ﷺ-এর দোয়া।"),
        "dua_useless_knowledge" to DuaText("অনুপকারী জ্ঞান থেকে আশ্রয়", "হে আল্লাহ! আমি তোমার আশ্রয় চাই এমন জ্ঞান থেকে যা উপকার দেয় না, এমন অন্তর থেকে যা ভয় করে না, এমন নফস থেকে যা তৃপ্ত হয় না এবং এমন দোয়া থেকে যা কবুল হয় না।", "অনুপকারী জ্ঞান ও ভয়হীন অন্তর থেকে আশ্রয়।", "নবী ﷺ-এর আশ্রয়ের দোয়া।"),
        "dua_beneficial_knowledge" to DuaText("উপকারী জ্ঞান ও হালাল রিজিক", "হে আল্লাহ! আমি তোমার কাছে উপকারী জ্ঞান, পবিত্র রিজিক ও কবুলযোগ্য আমল চাই।", "ফজরের নামাজের পর।", "নবী ﷺ ফজরের সালামের পর এই দোয়া করতেন।"),
        "dua_leprosy_diseases" to DuaText("কঠিন রোগ থেকে আশ্রয়", "হে আল্লাহ! আমি তোমার আশ্রয় চাই শ্বেতী, পাগলামি, কুষ্ঠ এবং সব ধরনের খারাপ রোগ থেকে।", "খারাপ রোগ থেকে হেফাজত।", "স্বাস্থ্য রক্ষার মাসনুন দোয়া।"),
        "dua_fear_people" to DuaText("শত্রু বা জালিমের ভয়", "হে আল্লাহ! আমরা তোমাকে তাদের মোকাবেলায় রাখছি এবং তাদের অনিষ্ট থেকে তোমার আশ্রয় চাই।", "কোনো সম্প্রদায় বা ব্যক্তির অনিষ্টের ভয় হলে।", "নবী ﷺ কোনো সম্প্রদায় থেকে বিপদ আশঙ্কা করলে এটি বলতেন।"),
        "dua_shirk_protection" to DuaText("গোপন শিরক থেকে হেফাজত", "হে আল্লাহ! আমি তোমার আশ্রয় চাই জেনেশুনে তোমার সাথে শিরক করা থেকে, আর যা না জেনে হয় তার জন্য ক্ষমা চাই।", "লোকদেখানো ও গোপন শিরক থেকে বাঁচতে।", "গোপন শিরক পিঁপড়ার চলার চেয়েও সূক্ষ্ম।"),
        "dua_rain" to DuaText("বৃষ্টির সময়", "হে আল্লাহ! উপকারী বৃষ্টি বর্ষণ করো।", "বৃষ্টি হওয়ার সময়।", "বৃষ্টি দোয়া কবুলের সময়।"),
        "dua_after_rain" to DuaText("বৃষ্টির পর", "আল্লাহর অনুগ্রহ ও রহমতে আমাদের উপর বৃষ্টি হয়েছে।", "বৃষ্টির পর।", "যে এটি বলে সে আল্লাহর প্রতি ঈমানদার।"),
        "dua_istisqa" to DuaText("বৃষ্টি প্রার্থনা (ইস্তিসকা)", "হে আল্লাহ! আমাদের বৃষ্টি দাও (তিনবার)।", "বৃষ্টি না হলে।", "নবী ﷺ জুমার খুতবায় এই দোয়া করেন এবং বৃষ্টি হয়।"),
        "dua_heavy_rain" to DuaText("অতিবৃষ্টি", "হে আল্লাহ! আমাদের আশেপাশে (বর্ষণ করো), আমাদের উপর নয়।", "বৃষ্টি বেশি হলে।", "নবী ﷺ-এর দোয়ায় মেঘ সরে যায়।"),
        "dua_wind" to DuaText("ঝড়ো বাতাসে", "হে আল্লাহ! আমি তোমার কাছে এর কল্যাণ, এর মধ্যে যা আছে তার কল্যাণ এবং যা নিয়ে এটি পাঠানো হয়েছে তার কল্যাণ চাই, আর এর অনিষ্ট, এর মধ্যে যা আছে তার অনিষ্ট এবং যা নিয়ে পাঠানো হয়েছে তার অনিষ্ট থেকে তোমার আশ্রয় চাই।", "ঝড়ো বাতাস বা ঝড় বইলে।", "নবী ﷺ ঝড়ের সময় এই দোয়া করতেন।"),
        "dua_thunder" to DuaText("বজ্রধ্বনি শুনলে", "পবিত্র সেই সত্তা যাঁর প্রশংসাসহ বজ্র তাসবিহ পাঠ করে এবং ফেরেশতারাও তাঁর ভয়ে।", "বজ্রধ্বনি শুনলে — আব্দুল্লাহ ইবনে যুবাইর (রা.)-এর আমল।", "সূরা রাদ (১৩:১৩) থেকে গৃহীত।"),
        "dua_new_moon" to DuaText("নতুন চাঁদ দেখলে", "হে আল্লাহ! এই চাঁদকে আমাদের উপর বরকত, ঈমান, নিরাপত্তা ও ইসলামের সাথে উদিত করো। (হে চাঁদ!) আমার ও তোমার রব আল্লাহ।", "নতুন চাঁদ দেখে।", "প্রতি নতুন মাসের মাসনুন দোয়া।"),
        "dua_janaza_adult" to DuaText("জানাজার নামাজ (প্রাপ্তবয়স্ক)", "হে আল্লাহ! আমাদের জীবিত ও মৃত, উপস্থিত ও অনুপস্থিত, ছোট ও বড়, পুরুষ ও নারী সবাইকে ক্ষমা করো। হে আল্লাহ! আমাদের মধ্যে যাকে জীবিত রাখো তাকে ইসলামের উপর জীবিত রাখো, আর যাকে মৃত্যু দাও তাকে ঈমানের উপর মৃত্যু দাও।", "জানাজার তৃতীয় তাকবিরের পর।", "প্রাপ্তবয়স্ক মৃতের মাসনুন দোয়া।"),
        "dua_janaza_child" to DuaText("জানাজার নামাজ (শিশু)", "হে আল্লাহ! একে আমাদের জন্য অগ্রগামী (মেজবান) বানাও, একে আমাদের জন্য প্রতিদান ও সঞ্চয় বানাও, এবং একে আমাদের জন্য সুপারিশকারী ও যার সুপারিশ কবুল হয় এমন বানাও।", "নাবালক শিশুর জানাজায় (মেয়ে হলে 'ইজআলহা')।", "হানাফিদের কাছে প্রচলিত মাসনুন দোয়া।"),
        "dua_mayyit_awf" to DuaText("মৃতের জন্য বিস্তারিত দোয়া", "হে আল্লাহ! তাকে ক্ষমা করো, তার প্রতি দয়া করো, তাকে নিরাপত্তা দাও, তাকে মাফ করো, তার আপ্যায়ন সম্মানজনক করো, তার কবর প্রশস্ত করো, তাকে পানি, বরফ ও শিলা দিয়ে ধৌত করো এবং তাকে গুনাহ থেকে এমনভাবে পরিষ্কার করো যেমন সাদা কাপড় ময়লা থেকে পরিষ্কার করা হয়।", "জানাজায় বা মৃতের জন্য।", "আওফ ইবনে মালিক (রা.) কামনা করেছিলেন, হায় যদি এই মৃত আমি হতাম।"),
        "dua_visiting_graves" to DuaText("কবর জিয়ারত", "হে মুমিন ও মুসলিম ঘরবাসীরা, তোমাদের উপর শান্তি বর্ষিত হোক। আমরাও ইনশাআল্লাহ তোমাদের সাথে মিলিত হব। আমি আল্লাহর কাছে আমাদের ও তোমাদের জন্য নিরাপত্তা চাই।", "কবরস্থানে প্রবেশের সময়।", "কবর জিয়ারত মৃত্যু ও আখিরাতের কথা মনে করিয়ে দেয়।"),
        "dua_closing_eyes" to DuaText("মৃতের চোখ বন্ধ করার সময়", "হে আল্লাহ! (অমুক)-কে ক্ষমা করো, হেদায়েতপ্রাপ্তদের মধ্যে তার মর্যাদা বাড়াও, তার পেছনে যারা রইল তাদের মধ্যে তুমি তার স্থলাভিষিক্ত হও, হে জগতসমূহের রব! আমাদের ও তাকে ক্ষমা করো, তার কবর প্রশস্ত করো এবং তাতে আলো দাও।", "মৃতের চোখ বন্ধ করার সময় (নাম নিয়ে)।", "নবী ﷺ আবু সালামা (রা.)-এর জন্য এই দোয়া করেছেন।"),
        "dua_condolence" to DuaText("সমবেদনা (তাজিয়াত)", "নিশ্চয়ই আল্লাহরই যা তিনি নিয়েছেন এবং তাঁরই যা তিনি দিয়েছেন, আর তাঁর কাছে প্রত্যেক জিনিসের নির্দিষ্ট সময় আছে, অতএব ধৈর্য ধরো এবং সওয়াবের আশা রাখো।", "কারও মৃত্যুতে পরিবারকে সমবেদনা জানাতে।", "নবী ﷺ তাঁর কন্যাকে এই বার্তা পাঠিয়েছিলেন।"),
        "dua_placing_in_grave" to DuaText("মৃতকে কবরে রাখা", "আল্লাহর নামে এবং রাসুলুল্লাহ ﷺ-এর মিল্লাতের উপর।", "মৃতকে কবরে নামানোর সময়।", "দাফনের মাসনুন দোয়া।"),
        "dua_sneezing" to DuaText("হাঁচি দিলে", "সকল প্রশংসা আল্লাহর। — আল্লাহ তোমার প্রতি দয়া করুন। — আল্লাহ তোমাকে হেদায়েত দিন এবং তোমার অবস্থা সংশোধন করুন।", "হাঁচি দিলে; শ্রোতা 'ইয়ারহামুকাল্লাহ' বলবে, তারপর হাঁচিদাতা উত্তর দেবে।", "এটি এক মুসলিমের উপর অপর মুসলিমের হকের অন্তর্ভুক্ত।"),
        "dua_toilet_enter" to DuaText("শৌচাগারে প্রবেশ", "আল্লাহর নামে। হে আল্লাহ! আমি নাপাক পুরুষ ও নারী জিন থেকে তোমার আশ্রয় চাই।", "বাম পা দিয়ে শৌচাগারে প্রবেশের আগে।", "বিসমিল্লাহ জিন ও মানুষের সতরের মাঝে আড়াল হয়ে যায়।"),
        "dua_toilet_exit" to DuaText("শৌচাগার থেকে বের হওয়া", "(হে আল্লাহ!) আমি তোমার ক্ষমা চাই।", "ডান পা দিয়ে শৌচাগার থেকে বের হওয়ার সময়।", "নবী ﷺ শৌচাগার থেকে বের হয়ে এটি বলতেন।"),
        "dua_thanking" to DuaText("কাউকে ধন্যবাদ জানানো", "আল্লাহ তোমাকে উত্তম প্রতিদান দিন।", "কেউ উপকার করলে।", "যে এটি বলল সে প্রশংসার হক আদায় করল।"),
        "dua_love_for_allah" to DuaText("কেউ বললে 'আমি তোমাকে আল্লাহর জন্য ভালোবাসি'", "যাঁর জন্য তুমি আমাকে ভালোবাসো, তিনি (আল্লাহ) তোমাকে ভালোবাসুন।", "কেউ বললে 'আমি তোমাকে আল্লাহর জন্য ভালোবাসি'।", "আল্লাহর জন্য ভালোবাসার মাসনুন উত্তর।"),
        "dua_seeing_muslim_smile" to DuaText("সালাম", "তোমার উপর শান্তি, আল্লাহর রহমত ও তাঁর বরকত বর্ষিত হোক।", "মুসলিমের সাথে সাক্ষাতের সময়।", "পূর্ণ সালাম দিলে ত্রিশ নেকি পাওয়া যায়।"),
        "dua_dressing" to DuaText("কাপড় পরা", "সকল প্রশংসা আল্লাহর, যিনি আমাকে এই কাপড় পরিয়েছেন এবং আমার কোনো শক্তি ও সামর্থ্য ছাড়াই তা দান করেছেন।", "কাপড় পরার সময়।", "পূর্বের গুনাহ মাফের সুসংবাদ।"),
        "dua_rooster_donkey" to DuaText("মোরগ বা গাধার ডাক শুনলে", "হে আল্লাহ! আমি তোমার অনুগ্রহ চাই (মোরগ)। — আমি বিতাড়িত শয়তান থেকে আল্লাহর আশ্রয় চাই (গাধা)।", "মোরগের ডাকে আল্লাহর অনুগ্রহ চান, গাধার ডাকে শয়তান থেকে আশ্রয়।", "মোরগ ফেরেশতা দেখে আর গাধা শয়তান।"),
        "dua_something_liked" to DuaText("পছন্দনীয় কিছু দেখলে (বদনজর থেকে)", "আল্লাহ যা চেয়েছেন। হে আল্লাহ! এতে বরকত দাও।", "কারও ভালো কিছু দেখে বরকতের দোয়া দিন।", "বরকতের দোয়া দিলে নজর লাগে না।"),
        "dua_sell_buy_debt_repaid" to DuaText("ঋণ পরিশোধের সময়", "আল্লাহ তোমার পরিবার ও সম্পদে বরকত দিন।", "ঋণ ফেরত দেওয়ার সময় ঋণদাতার জন্য।", "ঋণের প্রতিদান হলো শুকরিয়া ও পরিশোধ।"),
        "dua_talbiyah" to DuaText("তালবিয়া", "আমি হাজির, হে আল্লাহ আমি হাজির। আমি হাজির, তোমার কোনো শরিক নেই, আমি হাজির। নিশ্চয়ই সকল প্রশংসা, নিয়ামত ও রাজত্ব তোমারই, তোমার কোনো শরিক নেই।", "ইহরাম বাঁধার পর উচ্চস্বরে।", "হজ ও উমরার প্রতীক।"),
        "dua_yamani_hajar" to DuaText("রুকনে ইয়ামানি ও হাজরে আসওয়াদের মাঝে", "হে আমাদের রব! আমাদের দুনিয়াতে কল্যাণ দাও এবং আখিরাতেও কল্যাণ দাও, আর আমাদের আগুনের আজাব থেকে রক্ষা করো।", "তাওয়াফে রুকনে ইয়ামানি ও হাজরে আসওয়াদের মাঝে।", "নবী ﷺ তাওয়াফে এই স্থানে এটি পড়তেন।"),
        "dua_safa_marwa" to DuaText("সাফা ও মারওয়ায়", "আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক, তাঁর কোনো শরিক নেই, রাজত্ব ও প্রশংসা তাঁরই এবং তিনি সব কিছুর উপর ক্ষমতাবান। আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক, তিনি তাঁর ওয়াদা পূর্ণ করেছেন, তাঁর বান্দাকে সাহায্য করেছেন এবং একাই সব বাহিনীকে পরাজিত করেছেন।", "সাফায় উঠে কিবলামুখী হয়ে (তিনবার)।", "সাফা ও মারওয়ায় নবী ﷺ-এর জিকির।"),
        "dua_arafah" to DuaText("আরাফার দিনের শ্রেষ্ঠ দোয়া", "আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক, তাঁর কোনো শরিক নেই, রাজত্ব ও প্রশংসা তাঁরই এবং তিনি সব কিছুর উপর ক্ষমতাবান।", "আরাফার দিন — সর্বোত্তম দোয়া।", "সর্বোত্তম দোয়া আরাফার দিনের দোয়া, আর সর্বোত্তম বাক্য এটি।"),
        "dua_takbeer_tashreeq" to DuaText("তাকবিরে তাশরিক", "আল্লাহ সবচেয়ে বড়, আল্লাহ সবচেয়ে বড়। আল্লাহ ছাড়া কোনো ইলাহ নেই। আল্লাহ সবচেয়ে বড়, আল্লাহ সবচেয়ে বড়, আর সকল প্রশংসা আল্লাহরই।", "৯ জিলহজ ফজর থেকে ১৩ জিলহজ আসর পর্যন্ত প্রত্যেক ফরজ নামাজের পর।", "আলী ও ইবনে মাসউদ (রা.) থেকে বর্ণিত — হানাফিদের কাছে ওয়াজিব।"),
        "dua_zamzam" to DuaText("জমজম পান করার সময়", "হে আল্লাহ! আমি তোমার কাছে উপকারী জ্ঞান, প্রশস্ত রিজিক এবং সব রোগ থেকে আরোগ্য চাই।", "জমজম পান করার সময় যে নিয়ত থাকে তার দোয়া করুন।", "জমজম যে নিয়তে পান করা হয় তার জন্যই (ইবনে মাজাহ ৩০৬২)।"),
        "dua_q_ma_khalaqta_batila" to DuaText("সৃষ্টি নিয়ে চিন্তা", "হে আমাদের রব! তুমি এসব অনর্থক সৃষ্টি করোনি, তুমি পবিত্র, অতএব আমাদের আগুনের আজাব থেকে রক্ষা করো।", "আসমান ও জমিনের সৃষ্টি নিয়ে চিন্তাশীলদের দোয়া।", "বোধসম্পন্নদের (উলুল আলবাব) দোয়া।"),
        "dua_q_sami_na_munadiyan" to DuaText("আমরা ঈমানের আহ্বানকারীকে শুনেছি", "হে আমাদের রব! আমরা এক আহ্বানকারীকে ঈমানের দিকে ডাকতে শুনেছি যে, তোমরা তোমাদের রবের উপর ঈমান আনো, তাই আমরা ঈমান এনেছি। হে আমাদের রব! আমাদের গুনাহ ক্ষমা করো, আমাদের মন্দগুলো মুছে দাও এবং আমাদের নেককারদের সাথে মৃত্যু দাও।", "ঈমান ও নেককারদের সাথে মৃত্যুর দোয়া।", "ক্ষমা ও উত্তম মৃত্যুর দোয়া।"),
        "dua_q_atina_ma_waadtana" to DuaText("যা ওয়াদা করেছ তা দাও", "হে আমাদের রব! তোমার রাসুলদের মাধ্যমে যা ওয়াদা করেছ তা আমাদের দাও এবং কিয়ামতের দিন আমাদের লাঞ্ছিত করো না, নিশ্চয়ই তুমি ওয়াদা ভঙ্গ করো না।", "কিয়ামতের লাঞ্ছনা থেকে আশ্রয়।", "আখিরাতে সম্মান কামনা।"),
        "dua_q_israfana" to DuaText("আমাদের বাড়াবাড়ি ক্ষমা করো", "হে আমাদের রব! আমাদের গুনাহ ও আমাদের কাজে বাড়াবাড়ি ক্ষমা করো, আমাদের পা দৃঢ় রাখো এবং কাফির সম্প্রদায়ের বিরুদ্ধে আমাদের সাহায্য করো।", "পূর্ববর্তী নবীদের সঙ্গীদের দোয়া।", "দৃঢ়তা ও ক্ষমার দোয়া।"),
        "dua_q_jamiun_nas" to DuaText("তুমি মানুষকে একত্র করবে", "হে আমাদের রব! নিশ্চয়ই তুমি মানুষকে এমন এক দিনে একত্র করবে যাতে কোনো সন্দেহ নেই। নিশ্চয়ই আল্লাহ ওয়াদা ভঙ্গ করেন না।", "কিয়ামতের প্রতি দৃঢ় বিশ্বাসের স্বীকৃতি।", "জ্ঞানে সুদৃঢ়দের দোয়া।"),
        "dua_q_maash_shahidin" to DuaText("আমাদের সাক্ষীদের সাথে লেখো", "হে আমাদের রব! আমরা ঈমান এনেছি, অতএব আমাদের সাক্ষ্যদাতাদের সাথে লিখে নাও।", "সত্য চিনে ঈমান আনয়নকারীদের দোয়া।", "ঈমান কবুলের দোয়া।"),
        "dua_q_la_tajalna_zalimin" to DuaText("জালিমদের সাথে রেখো না", "হে আমাদের রব! আমাদের জালিম সম্প্রদায়ের সাথে রেখো না।", "আরাফবাসীদের দোয়া।", "জালিমদের পরিণাম থেকে আশ্রয়।"),
        "dua_q_tawaffana_muslimin" to DuaText("ধৈর্য ও মুসলিম অবস্থায় মৃত্যু", "হে আমাদের রব! আমাদের উপর ধৈর্য ঢেলে দাও এবং আমাদের মুসলিম অবস্থায় মৃত্যু দাও।", "ফেরাউনের জাদুকররা ঈমান আনার সময়ের দোয়া।", "পরীক্ষায় ধৈর্য ও ঈমানের উপর মৃত্যু।"),
        "dua_q_la_tajalna_fitnah" to DuaText("জালিমদের জন্য পরীক্ষা বানিও না", "আমরা আল্লাহর উপর ভরসা করলাম। হে আমাদের রব! আমাদের জালিম সম্প্রদায়ের জন্য পরীক্ষার বস্তু বানিও না এবং তোমার রহমতে আমাদের কাফির সম্প্রদায় থেকে মুক্তি দাও।", "মুসা (আ.)-এর সম্প্রদায়ের দোয়া।", "জুলুম ও জালিম থেকে মুক্তির দোয়া।"),
        "dua_q_nuh_ma_laysa_li" to DuaText("ক্ষমার জন্য নূহ (আ.)-এর দোয়া", "হে আমার রব! আমি তোমার আশ্রয় চাই এমন কিছু চাওয়া থেকে যে বিষয়ে আমার জ্ঞান নেই। তুমি যদি আমাকে ক্ষমা না করো ও দয়া না করো, তবে আমি ক্ষতিগ্রস্তদের অন্তর্ভুক্ত হব।", "নূহ (আ.)-এর তওবার দোয়া।", "আদবের সাথে দোয়া করার শিক্ষা।"),
        "dua_q_mudkhala_sidq" to DuaText("সত্যের সাথে প্রবেশ ও প্রস্থান", "হে আমার রব! আমাকে সত্যের সাথে প্রবেশ করাও এবং সত্যের সাথে বের করো, আর তোমার পক্ষ থেকে আমাকে সাহায্যকারী শক্তি দান করো।", "কোনো নতুন কাজ, ঘর বা স্থানে প্রবেশের আগে।", "হিজরতের সময় নবী ﷺ-কে শেখানো দোয়া।"),
        "dua_q_la_tadharni_fardan" to DuaText("আমাকে একা রেখো না (জাকারিয়া আ.)", "হে আমার রব! আমাকে একা রেখো না, আর তুমিই শ্রেষ্ঠ উত্তরাধিকারী।", "সন্তান কামনায়।", "এই দোয়ার ফলে আল্লাহ ইয়াহইয়া (আ.)-কে দান করেন।"),
        "dua_q_munzalan_mubarakan" to DuaText("বরকতময় অবতরণস্থল", "হে আমার রব! আমাকে বরকতময় স্থানে অবতরণ করাও, আর তুমিই শ্রেষ্ঠ অবতরণকারী।", "নতুন বাসায় ওঠা বা কোথাও নামার সময় — নূহ (আ.)-এর দোয়া।", "নতুন স্থানে বরকতের দোয়া।"),
        "dua_q_amanna_faghfir" to DuaText("আমরা ঈমান এনেছি, ক্ষমা করো", "হে আমাদের রব! আমরা ঈমান এনেছি, অতএব আমাদের ক্ষমা করো ও দয়া করো, আর তুমিই শ্রেষ্ঠ দয়ালু।", "আল্লাহর নেক বান্দাদের দোয়া।", "ক্ষমা ও রহমতের ব্যাপক দোয়া।"),
        "dua_q_isrif_jahannam" to DuaText("জাহান্নামের আজাব ফিরিয়ে দাও", "হে আমাদের রব! আমাদের থেকে জাহান্নামের আজাব ফিরিয়ে দাও, নিশ্চয়ই এর আজাব স্থায়ী। নিশ্চয়ই তা নিকৃষ্ট আবাস ও স্থান।", "ইবাদুর রহমানের (রহমানের বান্দাদের) দোয়া।", "জাহান্নাম থেকে আশ্রয়ের কুরআনি দোয়া।"),
        "dua_q_hab_li_hukman" to DuaText("প্রজ্ঞা ও জান্নাত (ইবরাহিম আ.)", "হে আমার রব! আমাকে প্রজ্ঞা দান করো এবং নেককারদের সাথে মিলিত করো, পরবর্তীদের মধ্যে আমার সুনাম অব্যাহত রাখো, এবং আমাকে নিয়ামতপূর্ণ জান্নাতের উত্তরাধিকারীদের অন্তর্ভুক্ত করো।", "প্রজ্ঞা, নেককারদের সান্নিধ্য ও জান্নাত কামনা।", "ইবরাহিম (আ.)-এর ব্যাপক দোয়া।"),
        "dua_q_lut_najjini_ahli" to DuaText("আমার পরিবারকে রক্ষা করো (লুত আ.)", "হে আমার রব! আমাকে ও আমার পরিবারকে তাদের কর্মের (পরিণাম) থেকে মুক্তি দাও।", "মন্দ পরিবেশ থেকে পরিবারের হেফাজত।", "মন্দ থেকে পরিবারের হেফাজত।"),
        "dua_q_sulaiman_awzini" to DuaText("শুকরিয়ার জন্য সুলাইমান (আ.)-এর দোয়া", "হে আমার রব! আমাকে তাওফিক দাও যেন আমি তোমার সেই নিয়ামতের শুকরিয়া আদায় করি যা তুমি আমাকে ও আমার পিতা-মাতাকে দিয়েছ, এবং এমন নেক আমল করি যা তুমি পছন্দ করো, আর তোমার রহমতে আমাকে তোমার নেক বান্দাদের অন্তর্ভুক্ত করো।", "নিয়ামতের শুকরিয়া আদায়ের তাওফিক।", "সুলাইমান (আ.)-এর শুকরিয়ার দোয়া।"),
        "dua_q_musa_zalamtu" to DuaText("আমি নিজের উপর জুলুম করেছি (মুসা আ.)", "হে আমার রব! আমি নিজের উপর জুলুম করেছি, অতএব আমাকে ক্ষমা করো।", "ভুল হয়ে গেলে সঙ্গে সঙ্গে তওবা।", "আল্লাহ মুসা (আ.)-কে ক্ষমা করেছেন।"),
        "dua_q_musa_najjini" to DuaText("জালিমদের থেকে রক্ষা করো (মুসা আ.)", "হে আমার রব! আমাকে জালিম সম্প্রদায় থেকে মুক্তি দাও।", "জালিমদের ভয়ে।", "মিসর থেকে বের হওয়ার সময় মুসা (আ.)-এর দোয়া।"),
        "dua_q_lut_unsurni" to DuaText("ফাসাদকারীদের বিরুদ্ধে সাহায্য (লুত আ.)", "হে আমার রব! ফাসাদকারী সম্প্রদায়ের বিরুদ্ধে আমাকে সাহায্য করো।", "ফাসাদকারীদের মোকাবেলায় সাহায্য।", "সত্যের উপর অবিচলদের দোয়া।"),
        "dua_q_hab_li_salihin" to DuaText("নেক সন্তানের জন্য ইবরাহিম (আ.)-এর দোয়া", "হে আমার রব! আমাকে নেককার (সন্তান) দান করো।", "নেক সন্তান কামনা।", "এই দোয়ার ফলে ইসমাইল (আ.)-কে দান করা হয়।"),
        "dua_q_wasita_kulla_shay" to DuaText("আরশবাহী ফেরেশতাদের দোয়া", "হে আমাদের রব! তোমার রহমত ও জ্ঞান সব কিছুকে পরিবেষ্টন করে আছে, অতএব যারা তওবা করেছে ও তোমার পথ অনুসরণ করেছে তাদের ক্ষমা করো এবং তাদের জাহান্নামের আজাব থেকে রক্ষা করো।", "আরশবাহী ফেরেশতারা মুমিনদের জন্য এই দোয়া করেন।", "ফেরেশতাদের দোয়ায় শামিল হওয়ার নিয়তে।"),
        "dua_q_ikhwanina" to DuaText("আমাদের পূর্ববর্তী ভাইদের জন্য", "হে আমাদের রব! আমাদের এবং আমাদের সেই ভাইদের ক্ষমা করো যারা আমাদের আগে ঈমান এনেছে, আর আমাদের অন্তরে মুমিনদের প্রতি কোনো বিদ্বেষ রেখো না। হে আমাদের রব! নিশ্চয়ই তুমি অতি স্নেহশীল, দয়ালু।", "পূর্ববর্তী মুমিনদের জন্য ও অন্তর পরিষ্কারের দোয়া।", "সাহাবায়ে কেরাম (রা.) ও পূর্ববর্তী মুমিনদের জন্য দোয়া।"),
        "dua_q_alayka_tawakkalna" to DuaText("তোমার উপরই আমরা ভরসা করি (ইবরাহিম আ.)", "হে আমাদের রব! আমরা তোমার উপর ভরসা করেছি, তোমার দিকে ফিরেছি এবং তোমারই দিকে প্রত্যাবর্তন। হে আমাদের রব! আমাদের কাফিরদের জন্য পরীক্ষার বস্তু বানিও না এবং আমাদের ক্ষমা করো। হে আমাদের রব! নিশ্চয়ই তুমি পরাক্রমশালী, প্রজ্ঞাময়।", "ইবরাহিম (আ.) ও তাঁর সঙ্গীদের দোয়া।", "তাওয়াক্কুল ও প্রত্যাবর্তনের দোয়া।"),
        "dua_q_atmim_nurana" to DuaText("আমাদের নূর পূর্ণ করো", "হে আমাদের রব! আমাদের জন্য আমাদের নূর পূর্ণ করো এবং আমাদের ক্ষমা করো, নিশ্চয়ই তুমি সব কিছুর উপর ক্ষমতাবান।", "কিয়ামতের দিন মুমিনদের দোয়া।", "পুলসিরাতে নূর কামনা।"),
        "dua_q_asiya_baytan" to DuaText("জান্নাতে ঘর (আসিয়া)", "হে আমার রব! তোমার কাছে জান্নাতে আমার জন্য একটি ঘর বানাও, আমাকে ফেরাউন ও তার কর্ম থেকে মুক্তি দাও এবং জালিম সম্প্রদায় থেকে মুক্তি দাও।", "ফেরাউনের স্ত্রী আসিয়ার দোয়া।", "আল্লাহ তাঁকে মুমিনদের জন্য দৃষ্টান্ত বানিয়েছেন।"),
        "dua_adhan_response" to DuaText("আজানের জবাব", "আল্লাহ ছাড়া কোনো শক্তি নেই, কোনো ক্ষমতা নেই।", "মুয়াজ্জিন যা বলে তা-ই বলুন; 'হাইয়া আলাস সালাহ' ও 'হাইয়া আলাল ফালাহ'-তে এটি বলুন।", "অন্তর থেকে জবাবদাতা জান্নাতে প্রবেশ করবে।"),
        "dua_adhan_shahadah" to DuaText("মুয়াজ্জিনের শাহাদাতের পর", "আমিও সাক্ষ্য দিচ্ছি যে আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক, তাঁর কোনো শরিক নেই, এবং মুহাম্মাদ ﷺ তাঁর বান্দা ও রাসুল। আমি আল্লাহকে রব, মুহাম্মাদ ﷺ-কে রাসুল এবং ইসলামকে দ্বীন হিসেবে পেয়ে সন্তুষ্ট।", "মুয়াজ্জিনের শাহাদাতাইন শুনে।", "তার গুনাহ ক্ষমা করা হয়।"),
        "dua_istiftah_baid" to DuaText("শুরুর দোয়া: আমাকে গুনাহ থেকে দূরে রাখো", "হে আল্লাহ! আমার ও আমার গুনাহের মাঝে এত দূরত্ব করে দাও যত দূরত্ব তুমি পূর্ব ও পশ্চিমের মাঝে করেছ। হে আল্লাহ! আমাকে গুনাহ থেকে এমনভাবে পরিষ্কার করো যেমন সাদা কাপড় ময়লা থেকে পরিষ্কার করা হয়। হে আল্লাহ! আমার গুনাহ পানি, বরফ ও শিলা দিয়ে ধুয়ে দাও।", "তাকবিরে তাহরিমার পর (সানার পরিবর্তেও পড়া যায়)।", "নবী ﷺ তাকবির ও কিরাতের মাঝে এটি পড়তেন।"),
        "dua_hamdan_kathiran" to DuaText("রুকুর পর অধিক প্রশংসা", "হে আমাদের রব! তোমারই জন্য প্রশংসা — অনেক, পবিত্র ও বরকতময় প্রশংসা।", "রুকু থেকে উঠে 'রাব্বানা লাকাল হামদ'-এর সাথে।", "ত্রিশেরও বেশি ফেরেশতা এটি আগে লেখার জন্য প্রতিযোগিতা করছিলেন।"),
        "dua_subbuhun_quddus" to DuaText("সুব্বুহুন কুদ্দুস (রুকু ও সিজদা)", "(আল্লাহ) অতি পবিত্র, অতি মহিমান্বিত, ফেরেশতা ও রুহের (জিবরাইলের) রব।", "রুকু ও সিজদায়।", "নবী ﷺ রুকু ও সিজদায় এটি পড়তেন।"),
        "dua_sujood_dhanbi_kullah" to DuaText("সিজদায়: আমার সব গুনাহ ক্ষমা করো", "হে আল্লাহ! আমার সব গুনাহ ক্ষমা করো — ছোট ও বড়, আগের ও পরের, প্রকাশ্য ও গোপন।", "সিজদায়।", "সিজদা দোয়া কবুলের স্থান।"),
        "dua_sujood_ridaka" to DuaText("তোমার সন্তুষ্টির আশ্রয়", "হে আল্লাহ! আমি তোমার সন্তুষ্টির মাধ্যমে তোমার অসন্তুষ্টি থেকে, তোমার ক্ষমার মাধ্যমে তোমার শাস্তি থেকে আশ্রয় চাই, এবং তোমার কাছে তোমার থেকেই আশ্রয় চাই। আমি তোমার প্রশংসা গুনে শেষ করতে পারি না, তুমি তেমনই যেমন তুমি নিজের প্রশংসা করেছ।", "সিজদায় — আয়েশা (রা.) নবী ﷺ-কে এটি পড়তে শুনেছেন।", "নবী ﷺ-এর সিজদার দোয়া।"),
        "dua_tashahhud" to DuaText("তাশাহহুদ (আত্তাহিয়্যাত)", "সকল মৌখিক, শারীরিক ও আর্থিক ইবাদত আল্লাহর জন্য। হে নবী! আপনার উপর সালাম, আল্লাহর রহমত ও তাঁর বরকত। আমাদের উপর ও আল্লাহর নেক বান্দাদের উপর সালাম। আমি সাক্ষ্য দিচ্ছি যে আল্লাহ ছাড়া কোনো ইলাহ নেই এবং সাক্ষ্য দিচ্ছি যে মুহাম্মাদ ﷺ তাঁর বান্দা ও রাসুল।", "প্রত্যেক বৈঠকে — আব্দুল্লাহ ইবনে মাসউদ (রা.)-এর বর্ণনা (হানাফিদের আমল)।", "নবী ﷺ এটি কুরআনের সূরার মতো শেখাতেন।"),
        "dua_sajdah_tilawah" to DuaText("তিলাওয়াতের সিজদা", "আমার চেহারা সিজদা করল সেই সত্তাকে যিনি একে সৃষ্টি করেছেন এবং নিজ শক্তি ও ক্ষমতায় এর কান ও চোখ বানিয়েছেন।", "তিলাওয়াতের সিজদায়।", "নবী ﷺ রাতে তিলাওয়াতের সিজদায় এটি পড়তেন।"),
        "dua_after_witr" to DuaText("বিতরের পর", "পবিত্র সেই বাদশাহ, অতি পবিত্র।", "বিতরের সালামের পর তিনবার, তৃতীয়বার উচ্চস্বরে।", "নবী ﷺ বিতরের পর এটি বলতেন।"),
        "dua_tahajjud_nur" to DuaText("তাহাজ্জুদের শুরুর দোয়া", "হে আল্লাহ! তোমারই জন্য প্রশংসা, তুমি আসমান, জমিন ও এগুলোর মধ্যে যা আছে সবকিছুর ধারক। তোমারই জন্য প্রশংসা, তুমি আসমান, জমিন ও এগুলোর মধ্যে যা আছে সবকিছুর নূর। তোমারই জন্য প্রশংসা, তুমি সত্য, তোমার ওয়াদা সত্য, তোমার সাক্ষাৎ সত্য, তোমার বাণী সত্য, জান্নাত সত্য, জাহান্নাম সত্য, নবীগণ সত্য, মুহাম্মাদ ﷺ সত্য এবং কিয়ামত সত্য।", "রাতের নামাজ (তাহাজ্জুদ) শুরুর সময় (দোয়ার শুরুর অংশ)।", "নবী ﷺ তাহাজ্জুদের জন্য উঠে এটি পড়তেন (পূর্ণ দোয়া বুখারিতে আছে)।"),
        "dua_rabba_jibrail" to DuaText("মতভেদপূর্ণ বিষয়ে পথনির্দেশ", "হে আল্লাহ, জিবরাইল, মিকাইল ও ইসরাফিলের রব, আসমান ও জমিনের স্রষ্টা, গোপন ও প্রকাশ্যের জ্ঞাতা! তুমি তোমার বান্দাদের মাঝে সেসব বিষয়ে ফয়সালা করবে যাতে তারা মতভেদ করত। যে সত্যে মতভেদ করা হয়েছে, তোমার অনুমতিতে আমাকে তার পথ দেখাও। নিশ্চয়ই তুমি যাকে চাও সরল পথ দেখাও।", "তাহাজ্জুদের শুরুতে — মতভেদের সময় সত্যের পথনির্দেশ।", "নবী ﷺ এই দোয়া দিয়ে রাতের নামাজ শুরু করতেন।"),
        "dua_going_to_mosque_nur" to DuaText("মসজিদে যাওয়ার সময় (নূরের দোয়া)", "হে আল্লাহ! আমার অন্তরে নূর দাও, আমার চোখে নূর, আমার কানে নূর, আমার ডানে নূর, আমার বামে নূর, আমার উপরে নূর, আমার নিচে নূর, আমার সামনে নূর, আমার পেছনে নূর, এবং আমার জন্য নূর বানিয়ে দাও।", "ফজরের জন্য মসজিদে যাওয়ার সময়।", "নবী ﷺ নামাজের জন্য বের হতে এটি পড়তেন।"),
        "dua_waswasa_salah" to DuaText("নামাজে ওয়াসওয়াসা (খিনযাব)", "আমি বিতাড়িত শয়তান থেকে আল্লাহর আশ্রয় চাই।", "নামাজে শয়তানি ওয়াসওয়াসা এলে আশ্রয় চেয়ে বাম দিকে তিনবার হালকা থুথু ফেলুন।", "উসমান ইবনে আবিল আস (রা.) এটি করলেন এবং ওয়াসওয়াসা চলে গেল।"),
        "dua_alimal_ghayb" to DuaText("অদৃশ্যের জ্ঞাতা", "হে আল্লাহ, অদৃশ্য ও দৃশ্যের জ্ঞাতা, আসমান ও জমিনের স্রষ্টা, সব কিছুর রব ও মালিক! আমি সাক্ষ্য দিচ্ছি যে তুমি ছাড়া কোনো ইলাহ নেই। আমি আমার নফসের অনিষ্ট থেকে এবং শয়তানের অনিষ্ট ও তার শিরক থেকে তোমার আশ্রয় চাই।", "সকাল, সন্ধ্যা ও ঘুমানোর আগে — নবী ﷺ আবু বকর (রা.)-কে শিখিয়েছেন।", "নফস ও শয়তানের অনিষ্ট থেকে হেফাজত।"),
        "dua_fitratil_islam" to DuaText("ইসলামের ফিতরাতের উপর", "আমরা সকালে উপনীত হলাম ইসলামের ফিতরাতের উপর, ইখলাসের কালিমার উপর, আমাদের নবী মুহাম্মাদ ﷺ-এর দ্বীনের উপর এবং আমাদের পিতা ইবরাহিম (আ.)-এর মিল্লাতের উপর, যিনি একনিষ্ঠ মুসলিম ছিলেন এবং মুশরিকদের অন্তর্ভুক্ত ছিলেন না।", "সকালে।", "প্রতি সকালে ঈমানের নবায়ন।"),
        "dua_amsayna_fitrah" to DuaText("সন্ধ্যায় ইসলামের ফিতরাতের উপর", "আমরা সন্ধ্যায় উপনীত হলাম ইসলামের ফিতরাতের উপর, ইখলাসের কালিমার উপর, আমাদের নবী মুহাম্মাদ ﷺ-এর দ্বীনের উপর এবং আমাদের পিতা ইবরাহিম (আ.)-এর মিল্লাতের উপর, যিনি একনিষ্ঠ মুসলিম ছিলেন এবং মুশরিকদের অন্তর্ভুক্ত ছিলেন না।", "সন্ধ্যায়।", "প্রতি সন্ধ্যায় ঈমানের নবায়ন।"),
        "dua_tahleel_10_fajr" to DuaText("ফজর ও মাগরিবের পর দশবার তাহলিল", "আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক, তাঁর কোনো শরিক নেই, রাজত্ব ও প্রশংসা তাঁরই, তিনিই জীবন দেন ও মৃত্যু দেন, এবং তিনি সব কিছুর উপর ক্ষমতাবান।", "ফজর (ও মাগরিব)-এর পর, পা না ঘুরিয়ে ও কথা না বলে দশবার।", "দশ নেকি, দশ গুনাহ মাফ, দশ মর্যাদা বৃদ্ধি এবং সারাদিন শয়তান থেকে হেফাজত।"),
        "dua_la_hawla_kanz" to DuaText("জান্নাতের ধনভান্ডার", "আল্লাহ ছাড়া কোনো শক্তি নেই, কোনো ক্ষমতা নেই।", "সবসময় বেশি বেশি।", "এটি জান্নাতের ধনভান্ডারগুলোর একটি।"),
        "dua_four_beloved_words" to DuaText("সবচেয়ে প্রিয় চারটি বাক্য", "আল্লাহ পবিত্র, সকল প্রশংসা আল্লাহর, আল্লাহ ছাড়া কোনো ইলাহ নেই এবং আল্লাহ সবচেয়ে বড়।", "আল্লাহর কাছে সবচেয়ে প্রিয় বাক্য।", "নবী ﷺ-এর কাছে এগুলো সূর্য যার উপর উদিত হয় তার সবকিছুর চেয়ে প্রিয়।"),
        "dua_two_light_words" to DuaText("জিহ্বায় হালকা দুটি বাক্য", "আল্লাহ পবিত্র এবং সকল প্রশংসা তাঁর; মহান আল্লাহ পবিত্র।", "জিহ্বায় হালকা, মিজানে ভারী।", "রহমানের কাছে প্রিয়, জিহ্বায় হালকা ও মিজানে ভারী। (বুখারির শেষ হাদিস)"),
        "dua_ya_dhal_jalal" to DuaText("ইয়া যাল জালালি ওয়াল ইকরাম", "হে মহিমা ও সম্মানের অধিকারী!", "দোয়ায় এটি আঁকড়ে ধরো — নবী ﷺ-এর নির্দেশ।", "নবী ﷺ বলেছেন: 'ইয়া যাল জালালি ওয়াল ইকরাম' আঁকড়ে ধরো।"),
        "dua_sleep_wadatu_janbi" to DuaText("তোমার নামে আমি পাশ রাখলাম", "হে আমার রব! তোমার নামে আমি আমার পাশ রাখলাম এবং তোমার নামেই উঠব। যদি তুমি আমার রুহ আটকে রাখো তবে তার প্রতি দয়া করো, আর যদি ছেড়ে দাও তবে তাকে এমনভাবে হেফাজত করো যেমন তুমি তোমার নেক বান্দাদের হেফাজত করো।", "বিছানা ঝেড়ে শোয়ার পর।", "ঘুমানোর আগে রুহ আল্লাহর কাছে সোপর্দ করা।"),
        "dua_sleep_khalaqta_nafsi" to DuaText("তুমি আমার প্রাণ সৃষ্টি করেছ", "হে আল্লাহ! তুমি আমার প্রাণ সৃষ্টি করেছ এবং তুমিই তার মৃত্যু দেবে। তার মৃত্যু ও জীবন তোমারই জন্য। যদি তাকে জীবিত রাখো তবে তার হেফাজত করো, আর যদি মৃত্যু দাও তবে তাকে ক্ষমা করো। হে আল্লাহ! আমি তোমার কাছে নিরাপত্তা চাই।", "ঘুমানোর আগে — ইবনে উমর (রা.)-এর বর্ণনা।", "নবী ﷺ ঘুমানোর সময় এটি পড়ার আদেশ দিয়েছেন।"),
        "dua_sleep_atamana" to DuaText("ঘুমানোর আগে শুকরিয়া", "সকল প্রশংসা আল্লাহর, যিনি আমাদের খাইয়েছেন, পান করিয়েছেন, আমাদের প্রয়োজন মিটিয়েছেন এবং আশ্রয় দিয়েছেন। কত মানুষ আছে যাদের প্রয়োজন মেটানোর কেউ নেই, আশ্রয় দেওয়ারও কেউ নেই।", "বিছানায় যাওয়ার সময়।", "নবী ﷺ বিছানায় যাওয়ার সময় এটি বলতেন।"),
        "dua_sleep_rabbas_samawat" to DuaText("আসমানের রব — আমাদের ঋণ শোধ করো", "হে আল্লাহ, আসমানসমূহ, জমিন ও মহান আরশের রব, আমাদের ও সব কিছুর রব, বীজ ও আঁটি বিদীর্ণকারী, তাওরাত, ইঞ্জিল ও ফুরকান নাজিলকারী! আমি প্রত্যেক সেই জিনিসের অনিষ্ট থেকে তোমার আশ্রয় চাই যার কপাল তোমার হাতে। হে আল্লাহ! তুমিই প্রথম, তোমার আগে কিছু নেই; তুমিই শেষ, তোমার পরে কিছু নেই; তুমিই প্রকাশ্য, তোমার উপরে কিছু নেই; তুমিই গোপন, তোমার থেকে গোপন কিছু নেই। আমাদের ঋণ পরিশোধ করে দাও এবং আমাদের দারিদ্র্য থেকে মুক্ত করো।", "ঘুমানোর আগে ডান কাতে — ফাতিমা (রা.)-কে শেখানো।", "ঋণ ও অভাব থেকে মুক্তির দোয়া।"),
        "dua_sleep_fear" to DuaText("ঘুমে ভয় বা অস্থিরতা", "আমি আল্লাহর পরিপূর্ণ কালিমাসমূহের আশ্রয় চাই তাঁর ক্রোধ ও শাস্তি থেকে, তাঁর বান্দাদের অনিষ্ট থেকে এবং শয়তানদের কুমন্ত্রণা ও তাদের আমার কাছে আসা থেকে।", "ঘুমে অস্থিরতা বা ভয় লাগলে।", "এমন করলে সেই জিনিস ক্ষতি করবে না।"),
        "dua_waking_afani" to DuaText("জাগার পর: তিনি আমার রুহ ফিরিয়ে দিয়েছেন", "সকল প্রশংসা আল্লাহর, যিনি আমার শরীরে সুস্থতা দিয়েছেন, আমার রুহ আমাকে ফিরিয়ে দিয়েছেন এবং তাঁর জিকির করার সুযোগ দিয়েছেন।", "জাগার পর।", "নতুন সকালের জন্য শুকরিয়া।"),
        "dua_allahu_rabbi" to DuaText("আল্লাহ, আল্লাহ আমার রব", "আল্লাহ, আল্লাহ আমার রব, আমি তাঁর সাথে কোনো কিছুকে শরিক করি না।", "দুঃখ বা দুশ্চিন্তার সময় — নবী ﷺ আসমা বিনতে উমাইস (রা.)-কে শিখিয়েছেন।", "দুশ্চিন্তার সময় তাওহিদের আশ্রয়।"),
    )
}
